  "ui.bricksExtensions.modules.7": "Bricks のログイン認証、アカウント設定、認証アプリ、メールコード、パスキーを追加します。",
  "ui.bricksExtensions.modules.8": "グラデーションの縞模様を修正",
  "ui.bricksExtensions.modules.9": "Bricks 要素のネイティブなグラデーション設定に、任意で有効にできるスムージング切り替えを追加します。",
  "ui.bricksExtensions.modules.10": "GSAP と選択したアニメーション拡張をサイト全体、または有効にした Bricks ページだけに読み込みます。",
  "ui.bricksExtensions.modules.11": "Pixflow Library のスライダー矢印と進行バーをサイト全体またはページごとに有効にします。",
  "ui.bricksExtensions.cookie_platforms.12": "Microsoft の同意の既定値と更新をキューに追加します。",
  "ui.bricksExtensions.cookie_platforms.13": "Meta の許可・取り消しコマンドを送信します。",
  "ui.bricksExtensions.cookie_platforms.14": "Pinterest の同意コマンドを送信します。",
  "ui.bricksExtensions.cookie_platforms.15": "設定済みの TikTok トラッキングを同意後にのみ許可します。",
  "ui.bricksExtensions.cookie_platforms.16": "設定済みの Snapchat トラッキングを同意後にのみ許可します。",
  "ui.bricksExtensions.cookie_platforms.17": "設定済みの LinkedIn トラッキングを同意後にのみ許可します。",
  "ui.bricksExtensions.cookie_services.18": "YouTube 埋め込み",
  "ui.bricksExtensions.cookie_services.19": "Vimeo 埋め込み",
  "ui.bricksExtensions.two_factor_methods.20": "対応する 6 桁の認証アプリでの設定を許可します。",
  "ui.bricksExtensions.two_factor_methods.21": "ユーザーの WordPress アカウントのメールアドレスに短時間有効なコードを送信できます。",
  "ui.bricksExtensions.two_factor_methods.22": "Windows Hello、Touch ID、Face ID、生体認証、FIDO2 キーを許可します。",
